<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import type { Locale } from '../content/pages'
import { applicationPayload, emptyApplication, type PartnerKind } from '../content/partnerApplication'
const props=defineProps<{kind:PartnerKind;locale:Locale}>()
const draft=reactive(emptyApplication()),acknowledged=ref(false),busy=ref(false),error=ref(''),receipt=ref(''),pending=ref<ReturnType<typeof applicationPayload>|null>(null),locating=ref(false)
let alive=true
onBeforeUnmount(()=>{alive=false})
const copy=computed(()=>props.locale==='fr'?{
 title:props.kind==='RIDER'?'Votre candidature livreur.':props.kind==='VENDOR'?'Votre boutique avec SEQUO.':'Proposez votre point relais.',
 intro:'Remplissez vos informations. L’équipe SEQUO les examine et vous contacte avant de valider le partenariat. Vous n’avez pas besoin de créer un compte pour candidater.',
 name:'Votre nom complet',email:'Email',phone:'Téléphone avec indicatif',contact:'Indiquez au moins un email ou un numéro de téléphone où vous joindre.',business:props.kind==='HUB'?'Nom du point relais':'Nom de la boutique',city:'Ville',neighborhood:'Quartier',directions:'Adresse ou indications utiles',vehicle:'Votre véhicule',choose:'Choisir',moto:'Moto / scooter',bicycle:'Vélo',car:'Voiture',van:'Fourgon',position:'Position de la boutique (facultatif)',positionHelp:'Si vous êtes sur place, vous pouvez partager sa position. Vous pouvez aussi saisir les coordonnées. Sinon, l’équipe les confirmera avec vous.',locate:'Utiliser ma position actuelle',locating:'Recherche de la position…',latitude:'Latitude',longitude:'Longitude',consent:'Je confirme ces informations et j’accepte que SEQUO me contacte au sujet de cette candidature.',privacy:'Confidentialité de vos informations',send:'Envoyer ma candidature',sending:'Envoi…',retry:'Réessayer le même envoi',success:'Candidature reçue.',successText:'L’équipe SEQUO va examiner vos informations. Votre candidature ne donne pas encore accès à un compte partenaire. Conservez cette référence pour échanger avec l’équipe.',reference:'Votre référence',again:'Déposer une autre candidature',note:'Aucun code personnel, document d’identité ou renseignement bancaire n’est demandé ici.',pending:'Un envoi est enregistré dans cet onglet. Réessayez avec les mêmes informations pour éviter un doublon.',failed:'L’envoi n’a pas pu être confirmé. Vos informations restent disponibles pour réessayer.',locationError:'La position n’a pas pu être obtenue. Vous pouvez compléter les coordonnées ou poursuivre sans les renseigner.',errors:{acknowledgement:'Confirmez que SEQUO peut examiner cette candidature et vous contacter.',required:'Complétez le nom, la ville, le quartier et le nom du commerce si demandé.',contact:'Indiquez un email ou un téléphone.',email:'Vérifiez votre adresse email.',phone:'Utilisez un numéro international, par exemple +228…',vehicle:'Choisissez votre véhicule.',coordinates:'Renseignez les deux coordonnées valides, ou laissez les deux champs vides.'}
}:{
 title:props.kind==='RIDER'?'Your rider application.':props.kind==='VENDOR'?'Bring your shop to SEQUO.':'Propose your relay point.',
 intro:'Fill in your details. The SEQUO team reviews them and contacts you before approving the partnership. You do not need an account to apply.',
 name:'Your full name',email:'Email',phone:'Phone with country code',contact:'Provide at least one email or phone number where the team can reach you.',business:props.kind==='HUB'?'Relay point name':'Shop name',city:'City',neighborhood:'Neighborhood',directions:'Address or useful directions',vehicle:'Your vehicle',choose:'Choose',moto:'Motorbike / scooter',bicycle:'Bicycle',car:'Car',van:'Van',position:'Shop location (optional)',positionHelp:'If you are at the shop, you can share its location. You can also enter coordinates. Otherwise, the team will confirm them with you.',locate:'Use my current location',locating:'Finding location…',latitude:'Latitude',longitude:'Longitude',consent:'I confirm these details and agree that SEQUO may contact me about this application.',privacy:'How your information is used',send:'Submit my application',sending:'Sending…',retry:'Retry the same submission',success:'Application received.',successText:'The SEQUO team will review your details. Applying does not yet provide partner account access. Keep this reference when contacting the team.',reference:'Your reference',again:'Submit another application',note:'Do not provide personal codes, identity documents or bank details in this form.',pending:'A submission is saved in this tab. Retry the same details to avoid duplicates.',failed:'The submission could not be confirmed. Your details remain available to retry.',locationError:'Location could not be obtained. You can enter coordinates or continue without them.',errors:{acknowledgement:'Confirm that SEQUO can review and contact you about this application.',required:'Complete the name, city, neighborhood and business name where requested.',contact:'Provide an email or phone number.',email:'Check your email address.',phone:'Use an international phone number, for example +228…',vehicle:'Choose your vehicle.',coordinates:'Provide both valid coordinates or leave both empty.'}
})
const storageKey=computed(()=>`sequo_partner_application:${props.kind}`)
onMounted(()=>{
 try {const saved=sessionStorage.getItem(storageKey.value);if(saved){const value=JSON.parse(saved);if(value.kind!==props.kind||!value.idempotencyKey||!value.details||value.acknowledged!==true)throw Error('invalid');pending.value=value;Object.assign(draft,{...value.details,email:value.details.email??'',phoneNumber:value.details.phoneNumber??'',businessName:value.details.businessName??'',landmark:value.details.landmark??'',vehicleType:value.details.vehicleType??'',latitude:value.details.latitude==null?'':String(value.details.latitude),longitude:value.details.longitude==null?'':String(value.details.longitude)});acknowledged.value=true}}
 catch {error.value=copy.value.failed}
})
function locate(){
 if(!navigator.geolocation){error.value=copy.value.locationError;return}
 locating.value=true;error.value=''
 navigator.geolocation.getCurrentPosition(position=>{if(!alive)return;draft.latitude=String(position.coords.latitude);draft.longitude=String(position.coords.longitude);locating.value=false},()=>{if(!alive)return;error.value=copy.value.locationError;locating.value=false},{enableHighAccuracy:true,timeout:12000,maximumAge:0})
}
async function submit(){
 if(busy.value)return;error.value=''
 try {if(!pending.value){const body=applicationPayload(props.kind,draft,acknowledged.value,crypto.randomUUID());sessionStorage.setItem(storageKey.value,JSON.stringify(body));pending.value=body}}
 catch(e){const key=e instanceof Error?e.message:'';error.value=copy.value.errors[key as keyof typeof copy.value.errors]??copy.value.failed;return}
 busy.value=true
 try {
  const response=await fetch('https://api.sequoservice.com/api/partner-applications',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(pending.value)})
  if(!alive)return
  if(!response.ok){if(response.status===400){sessionStorage.removeItem(storageKey.value);pending.value=null}throw Error(copy.value.failed)}
  const result=await response.json() as {id?:string;state?:string}
  if(typeof result.id!=='string'||!/^[a-f0-9-]{36}$/i.test(result.id)||result.state!=='RECEIVED')throw Error(copy.value.failed)
  receipt.value=result.id;sessionStorage.removeItem(storageKey.value);pending.value=null;Object.assign(draft,emptyApplication());acknowledged.value=false
 }catch(e){if(alive)error.value=e instanceof Error?e.message:copy.value.failed}finally{if(alive)busy.value=false}
}
</script>
<template>
<section id="partner-application" class="section-space wrap partner-application" aria-labelledby="partner-application-title">
 <div class="partner-intro"><span class="partner-step">01 · {{locale==='fr'?'Vous remplissez':'You fill it in'}} &nbsp; 02 · {{locale==='fr'?'SEQUO valide':'SEQUO reviews'}}</span><h2 id="partner-application-title">{{copy.title}}</h2><p>{{copy.intro}}</p></div>
 <div v-if="receipt" class="application-received" role="status"><span class="received-mark" aria-hidden="true">✓</span><h3>{{copy.success}}</h3><p>{{copy.successText}}</p><p class="application-receipt">{{copy.reference}}<strong>{{receipt}}</strong></p><button class="button" @click="receipt=''">{{copy.again}}</button></div>
 <form v-else @submit.prevent="submit" class="application-form"><p v-if="error" class="application-error" role="alert">{{error}}</p><p v-if="pending" class="application-pending" role="status">{{copy.pending}}</p>
 <fieldset :disabled="busy||pending!==null"><div class="application-grid"><label>{{copy.name}} *<input v-model="draft.displayName" required maxlength="160" autocomplete="name" /></label><label>{{copy.email}}<input v-model="draft.email" type="email" maxlength="254" autocomplete="email" /></label><label>{{copy.phone}}<input v-model="draft.phoneNumber" type="tel" maxlength="32" autocomplete="tel" placeholder="+228…" /></label><p class="application-contact-hint">{{copy.contact}}</p><label v-if="kind!=='RIDER'">{{copy.business}} *<input v-model="draft.businessName" required :maxlength="kind==='HUB'?120:160" autocomplete="organization" /></label><label>{{copy.city}} *<input v-model="draft.city" required maxlength="128" autocomplete="address-level2" /></label><label>{{copy.neighborhood}} *<input v-model="draft.neighborhood" required maxlength="128" autocomplete="address-level3" /></label><label v-if="kind==='RIDER'">{{copy.vehicle}} *<select v-model="draft.vehicleType" required><option value="" disabled>{{copy.choose}}</option><option value="Moto">{{copy.moto}}</option><option value="Bicycle">{{copy.bicycle}}</option><option value="Car">{{copy.car}}</option><option value="Van">{{copy.van}}</option></select></label><label class="application-wide">{{copy.directions}}<textarea v-model="draft.landmark" maxlength="500" rows="3" /></label></div>
 <details v-if="kind!=='RIDER'" class="application-position"><summary>{{copy.position}}</summary><p>{{copy.positionHelp}}</p><button type="button" class="text-link" :disabled="locating" @click="locate">{{locating?copy.locating:copy.locate}}</button><div class="application-grid"><label>{{copy.latitude}}<input v-model="draft.latitude" type="number" step="any" min="-90" max="90" /></label><label>{{copy.longitude}}<input v-model="draft.longitude" type="number" step="any" min="-180" max="180" /></label></div></details>
 <label class="application-consent"><input v-model="acknowledged" type="checkbox" required /><span>{{copy.consent}}</span></label></fieldset>
 <div class="application-footer"><div><p>{{copy.note}}</p><a :href="locale==='fr'?'/confidentialite':'/en/privacy'">{{copy.privacy}}</a></div><button class="button" :disabled="busy" type="submit">{{busy?copy.sending:pending?copy.retry:copy.send}} <span aria-hidden="true">↗</span></button></div>
 </form>
</section>
</template>
<style scoped>
.partner-application{scroll-margin-top:120px;display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.4fr);gap:clamp(32px,5vw,88px);align-items:start}.partner-intro h2{font-size:clamp(2rem,3.4vw,3.8rem);line-height:1.08;letter-spacing:-.045em;margin:22px 0}.partner-intro p{line-height:1.8;color:#596a61}.partner-step{font-size:.75rem;font-weight:700;color:#0b6b46;letter-spacing:.06em}.application-form,.application-received{padding:clamp(24px,3vw,42px);background:#f3f7f3;border:1px solid #dce6dc;border-radius:24px}.application-form fieldset{border:0;padding:0;margin:0;min-width:0}.application-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.application-grid label{display:grid;gap:8px;font-size:.88rem;font-weight:600;color:#254d3b}.application-grid input,.application-grid select,.application-grid textarea{width:100%;box-sizing:border-box;padding:13px 14px;font:inherit;font-weight:400;background:#fff;color:#183e2d;border:1px solid #cbd9ce;border-radius:10px;min-height:48px}.application-grid input:focus,.application-grid select:focus,.application-grid textarea:focus{outline:2px solid #0b6b46;outline-offset:2px}.application-wide,.application-contact-hint{grid-column:1/-1}.application-contact-hint{font-size:.78rem;color:#617268;margin:-8px 0 0}.application-position{border-top:1px solid #dce6dc;margin-top:24px;padding-top:20px}.application-position summary{cursor:pointer;color:#254d3b;font-weight:600}.application-position p{line-height:1.7;font-size:.85rem}.application-position button{margin-bottom:16px;background:none;border:0;cursor:pointer}.application-consent{display:flex;align-items:flex-start;gap:12px;margin-top:25px;font-size:.82rem;line-height:1.7}.application-consent input{width:18px;height:18px;flex-shrink:0;margin-top:4px;accent-color:#0b6b46}.application-footer{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-top:28px;flex-wrap:wrap}.application-footer p,.application-footer a{font-size:.75rem;line-height:1.7;max-width:340px}.application-footer a{text-decoration:underline}.application-footer .button{border:0;cursor:pointer}.application-error,.application-pending{padding:14px;border-radius:10px;background:#fff;color:#8b342a;font-size:.85rem;line-height:1.6}.application-pending{color:#254d3b}.application-received h3{font-size:2rem;letter-spacing:-.03em;margin:20px 0}.application-received p{line-height:1.8}.received-mark{display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:#0b6b46;color:white;font-size:1.4rem}.application-receipt{padding:16px;background:white;border-radius:12px;font-size:.8rem}.application-receipt strong{display:block;overflow-wrap:anywhere;margin-top:8px;font-size:.9rem}.application-received button{cursor:pointer;border:0;margin-top:12px}@media(max-width:900px){.partner-application{grid-template-columns:1fr}.partner-intro{max-width:650px}}@media(max-width:540px){.application-grid{grid-template-columns:1fr}.application-footer .button{width:100%;justify-content:center}.application-form{padding:22px}.partner-step{font-size:.65rem}}
</style>
